[[noreturn]] void rejectUrl(std::string_view url, const std::string &reason) {
  std::string message = "Invalid CREST server URL \"";
  message += url;
  message += "\": ";
  message += reason;
  message += URL_EXPECTED_FORM;
  throw Crest::CrestException(message);
}

