std::string Crest::StringUtils::makeUrl(const std::string &prefix,
                                        const std::string &host,
                                        const std::string &port,
                                        const std::string &address) {
  std::string str = prefix;
  str += "://";
  str += host;
  // An empty port means the caller never named one. Leaving it out lets the
  // transport apply the protocol default and keeps the URL as they wrote it.
  if (!port.empty()) {
    str += ':';
    str += port;
  }
  str += address;
  return str;
}

