std::optional<int> Crest::StringUtils::parsePort(
    std::string_view portStr) noexcept {
  if (portStr.empty()) {
    return std::nullopt;
  }

  // std::from_chars neither allocates nor throws, and it rejects what std::stoi
  // quietly accepts: leading whitespace, a leading '+', and a numeric prefix
  // followed by anything at all -- stoi reads "80abc" as 80, which would send
  // the request somewhere the caller never asked for.
  int port = 0;
  const char *const first = portStr.data();
  const char *const last = first + portStr.size();
  const std::from_chars_result parsed = std::from_chars(first, last, port);

  // from_chars stops at the first character it cannot use, so a parse that ends
  // early means the string held something other than a port.
  if (parsed.ec != std::errc() || parsed.ptr != last) {
    return std::nullopt;
  }

  if (port < MIN_PORT || port > MAX_PORT) {
    return std::nullopt;
  }

  return port;
}

