ParsedUrl Crest::StringUtils::parseUrl(std::string_view url) {
  const std::string_view originalUrl = url;
  ParsedUrl result;

  // Configuration files and command lines routinely pad a URL with whitespace,
  // which is not the caller getting it wrong. An all-whitespace or empty URL,
  // though, has nothing in it to parse.
  const size_t firstReal = url.find_first_not_of(WHITESPACE);
  if (firstReal == std::string_view::npos) {
    rejectUrl(originalUrl, "the URL is empty.");
  }
  url.remove_prefix(firstReal);
  url.remove_suffix(url.size() - 1 - url.find_last_not_of(WHITESPACE));

  const size_t protocolEnd = url.find("://");
  if (protocolEnd == std::string_view::npos) {
    rejectUrl(originalUrl, "there is no \"://\", so the protocol is missing.");
  }

  // RFC 3986 makes the scheme case-insensitive. Normalise it here so the rest
  // of the library only ever sees the canonical lowercase spelling.
  result.protocol = url.substr(0, protocolEnd);
  std::transform(
      result.protocol.begin(), result.protocol.end(), result.protocol.begin(),
      [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  if (result.protocol != "http" && result.protocol != "https") {
    rejectUrl(originalUrl, "\"" + result.protocol +
                               "\" is not a supported protocol; use http or "
                               "https.");
  }
  url.remove_prefix(protocolEnd + 3);  // find("://") proved these three exist.

  // Credentials belong in CREST_AUTH_MODE, not in the URL. Catching them here
  // by name beats letting the userinfo fall through to the host and port rules,
  // which would report something unrecognisable as a bad port.
  const size_t authorityEnd = url.find('/');
  if (url.substr(0, authorityEnd).find('@') != std::string_view::npos) {
    rejectUrl(originalUrl,
              "a user name or password in the URL is not supported; set "
              "CREST_AUTH_MODE instead.");
  }

  // The host runs up to the port or the api path, whichever arrives first.
  const size_t hostEnd = url.find_first_of(":/");
  result.host = url.substr(0, hostEnd);  // A count of npos means "to the end".
  if (result.host.empty()) {
    rejectUrl(originalUrl, "the host is empty.");
  }
  if (result.host.front() == '[') {
    rejectUrl(originalUrl,
              "IPv6 address literals are not supported; use a host name.");
  }
  if (hasUnusableCharacter(result.host)) {
    rejectUrl(originalUrl,
              "the host contains whitespace or a control character.");
  }
  // When there is no delimiter the host consumed the whole remainder. Assigning
  // an empty view says so without calling substr(npos), which throws, or
  // remove_prefix(npos), which is undefined and silently walks the view back
  // over the preceding '/'.
  url = (hostEnd == std::string_view::npos) ? std::string_view()
                                            : url.substr(hostEnd);

  // A port only when the caller wrote one. An absent port stays absent instead
  // of defaulting to 80/443: the transport already applies the protocol
  // default, and inventing one here puts a port in every URL that the caller
  // never asked for.
  if (!url.empty() && url.front() == ':') {
    url.remove_prefix(1);
    const size_t portEnd = url.find('/');
    const std::string_view portStr = url.substr(0, portEnd);
    // RFC 3986 gives the port as a possibly empty run of digits, so
    // "host:/path" names no port and means the same as "host/path". Only a port
    // the caller wrote and got wrong is a mistake worth refusing: dropping it
    // silently would fall back to the protocol default and reach the wrong
    // server.
    if (!portStr.empty()) {
      result.port = parsePort(portStr);
      if (!result.port.has_value()) {
        rejectUrl(originalUrl, "\"" + std::string(portStr) +
                                   "\" is not a valid port; expected a number "
                                   "from " +
                                   std::to_string(MIN_PORT) + " to " +
                                   std::to_string(MAX_PORT) + ".");
      }
    }
    url = (portEnd == std::string_view::npos) ? std::string_view()
                                              : url.substr(portEnd);
  }

  // Whatever is left is the api path. A trailing slash carries no meaning and
  // would otherwise show up doubled in every endpoint URL, and a lone "/" is
  // not a path at all.
  while (url.size() > 1 && url.back() == '/') {
    url.remove_suffix(1);
  }
  if (url.size() > 1) {
    if (hasUnusableCharacter(url)) {
      rejectUrl(originalUrl,
                "the api path contains whitespace or a control character.");
    }
    result.apipath = url;
  }

  return result;
}

