const std::string Crest::StringUtils::removeCR(const std::string &str) {
  // Copy the input string
  std::string str2 = str;
  // Replace all '\n' with '|'
  std::replace(str2.begin(), str2.end(), '\n', '|');

  // Erase all occurrences of '\r'
  str2.erase(std::remove(str2.begin(), str2.end(), '\r'), str2.end());

  return str2;
}

