std::string Crest::StringUtils::parseXMLOutput(
    const std::string_view xmlBuffer) {
  bool copy = true;

  std::string plainString = "";

  // remove all xml tags
  for (long unsigned int i = 0; i < xmlBuffer.length(); i++) {
    char convertc = xmlBuffer[i];

    if (convertc == '<')
      copy = false;
    else if (convertc == '>') {
      copy = true;
      continue;
    }

    if (copy)
      plainString += convertc;
  }

  return plainString;
}

