std::string Crest::StringUtils::getStringOr(const nlohmann::json &j,
                                            const std::string &key,
                                            const std::string &defaultValue) {
  if (!j.contains(key) || j.at(key).is_null()) {
    return defaultValue;
  }
  return j.at(key).get<std::string>();
}

