std::string Crest::StringUtils::getDateAndTime() {
  time_t now = time(0);
  struct tm tstruct;
  char buf[80];

  localtime_r(&now, &tstruct);
  strftime(buf, sizeof(buf), "%Y-%m-%d %X", &tstruct);
  return buf;
}
